    cost: 15,
    category: SpecialAbilityCategory.CombatStyle,
    prerequisiteText: "MU 13, Anführer",
    requirements: [{ type: "attribute", name: "MU", min: 13, text: "MU 13" }, { type: "specialAbility", name: "anfuhrer", text: "Anführer" }],
    effectText: "Bei der SF Anführer muss die Elenviner Kriegerin nur 1 freie Aktion statt einer regulären Aktion aufwenden.\nErweiterte Kampfsonderfertigkeiten: Binden, Schilddeckung, Waffenwurf",
