    cost: 15,
    category: SpecialAbilityCategory.CombatStyle,
    prerequisiteText: "MU 13",
    requirements: [{ type: "attribute", name: "MU", min: 13, text: "MU 13" }],
    effectText: "Wenn dem Korgeweihten mit einem Korspieß ein Wuchtschlag gelingt, kann er den W6 bei der TP-Bestimmung zweimal würfeln und das bessere Ergebnis wählen.\nErweiterte Kampfsonderfertigkeiten: Drei erweiterte Kampfsonderfertigkeiten nach Wahl des Helden aus der folgenden Liste: Aufspießen, Mächtiger Rundumschlag, Offensives Verhalten, Weiter Schwung, Windmühle",
    styleGrants: ["Drei erweiterte Kampfsonderfertigkeiten nach Wahl des Helden aus der folgenden Liste: Aufspießen","Mächtiger Rundumschlag","Offensives Verhalten","Weiter Schwung","Windmühle"],
    combatTechniques: ["Zweihandhiebwaffen (nur Korspieß)"],
    subCategory: "bewaffnet",
    sources: [{"book":"AG1","page":229},{"book":"KGW","page":240},{"book":"KSC","page":321}],
