    label: "Elementare Tarnung",
    cost: 10,
    category: SpecialAbilityCategory.MagicPact,
    prerequisiteText: "Elemente Eis oder Humus, Elementarpakt Stufe I",
    requirements: [{ type: "caster", text: "Zauberer" }, { type: "narrative", group: 1, text: "Elemente Eis" }, { type: "narrative", group: 1, text: "Humus" }, { type: "narrative", text: "Elementarpakt Stufe I" }],
    effectText: "Der Anwender wird innerhalb des Geländes des Elements für andere Kulturschaffende so gut wie unsichtbar, solange er nicht mit ihnen interagiert. Vergleichsproben auf Sinnesschärfe, um ihn zu entdecken, sind zusätzlich um …3 erschwert. Der Einsatz dieser Wirkung hält 6 Stunden an. Danach erleidet der Held 1 Stufe Betäubung.",
