    cost: 12,
    category: SpecialAbilityCategory.MagicPact,
    prerequisiteText: "Element Humus, Elementarpakt Stufe II",
    requirements: [{ type: "caster", text: "Zauberer" }, { type: "narrative", text: "Element Humus" }, { type: "narrative", text: "Elementarpakt Stufe II" }],
    effectText: "Alle im Wald lebenden Tiere greifen den Helden nicht an, sondern verhalten sich ihm gegenüber friedlich. Greift der Held das Tier an oder versucht ihm irgendwie zu schaden, endet die Wirkung sofort. Der Einsatz dieser Wirkung hält 6 Stunden an. Danach erleidet der Held 1 Stufe Betäubung.",
